use vstd::prelude::*;

verus! {
    // Compute the minimum element of a non‐empty vector of i8.
    // Postconditions:
    //   1) result equals some element of the input vector
    //   2) result is ≤ every element of the input vector
    fn nanmin(a: Vec<i8>) -> (result: i8)
        requires
            a.len() > 0,
        ensures
            // result is one of the array's elements
            exists j: nat :: j < a.len() && result == a.index(j),
            // result is minimum
            forall j: nat :: j < a.len() ==> result <= a.index(j),
    {
        // We scan from left to right, maintaining:
        //   idx: the next index to examine (1..=a.len())
        //   minv: the minimum over a[0..idx)
        let mut idx: usize = 1;
        let mut minv: i8 = a.index(0);
        // Loop until we've processed all entries
        while idx < a.len()
            invariant
                // idx is between 1 and a.len()
                0 < idx <= a.len(),
                // minv is ≤ every element seen so far
                forall k: nat :: k < idx ==> minv <= a.index(k),
                // minv equals one of the elements seen so far
                exists k: nat :: k < idx && minv == a.index(k),
            decreases
                a.len() - idx,
        {
            let x: i8 = a.index(idx);
            if x < minv {
                minv = x;
            }
            idx = idx + 1;
        }
        result = minv;
    }
}

